import sys
import os

def list_dir(path):
    result = []
    try:
        items = os.listdir(path)
        for item in items:
            full = os.path.join(path, item)
            if os.path.isdir(full):
                result.append(f"DIR:{item}")
            else:
                result.append(f"FILE:{item}")
    except Exception as e:
        result.append(f"ERROR:{str(e)}")
    return result

